package pe.edu.upeu.autoandes.service;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import java.util.List; import pe.edu.upeu.autoandes.dto.*; import pe.edu.upeu.autoandes.entity.*; import pe.edu.upeu.autoandes.repository.*; import pe.edu.upeu.autoandes.mapper.AutoAndesMapper; import pe.edu.upeu.autoandes.exception.DomainException;
@Service @RequiredArgsConstructor @Slf4j @Transactional(readOnly=true) public class CatalogoServiceImpl implements CatalogoService {
 private final ClienteRepository clientes; private final ServicioRepository servicios; private final VehiculoRepository vehiculos; private final OrdenServicioRepository ordenes; private final DetalleOrdenRepository detalles; private final AutoAndesMapper mapper;
 private Servicio s(Long id){return servicios.findById(id).orElseThrow(()->DomainException.missing("Servicio"));} private Vehiculo v(Long id){return vehiculos.findById(id).orElseThrow(()->DomainException.missing("Vehículo"));} private Cliente c(Long id){return clientes.findById(id).orElseThrow(()->DomainException.missing("Cliente"));}
 public List<ClienteResponseDTO> clientes(){return clientes.findAll().stream().map(mapper::cliente).toList();}
 public List<ServicioResponseDTO> servicios(){return servicios.findAll(org.springframework.data.domain.Sort.by("codigo")).stream().map(mapper::servicio).toList();}
 public ServicioResponseDTO servicio(Long id){return mapper.servicio(s(id));}
 @Transactional public ServicioResponseDTO crearServicio(ServicioRequestDTO d){if(servicios.existsByCodigo(d.codigo()))throw DomainException.conflict("El código de servicio ya existe");Servicio s=new Servicio();mapper.servicio(s,d);servicios.saveAndFlush(s);log.info("Servicio creado id={}",s.getId());return mapper.servicio(s);}
 @Transactional public void editarServicio(Long id,ServicioRequestDTO d){Servicio s=s(id);if(servicios.existsByCodigoAndIdNot(d.codigo(),id))throw DomainException.conflict("El código de servicio ya existe");mapper.servicio(s,d);servicios.flush();log.info("Servicio actualizado id={}",id);}
 @Transactional public void eliminarServicio(Long id){Servicio s=s(id);if(detalles.existsByServicioId(id))throw DomainException.conflict("El servicio tiene órdenes; utilice PATCH /servicios/"+id+"/estado para darlo de baja");servicios.delete(s);servicios.flush();log.info("Servicio eliminado id={}",id);}
 @Transactional public ServicioResponseDTO estadoServicio(Long id,boolean activo){Servicio s=s(id);s.setActivo(activo);servicios.flush();log.info("Estado de servicio id={} activo={}",id,activo);return mapper.servicio(s);}
 public List<VehiculoResponseDTO> vehiculos(Long clienteId){if(clienteId!=null)c(clienteId);return (clienteId==null?vehiculos.findAll():vehiculos.findByClienteId(clienteId)).stream().map(mapper::vehiculo).toList();}
 public VehiculoResponseDTO vehiculo(Long id){return mapper.vehiculo(v(id));}
 @Transactional public VehiculoResponseDTO crearVehiculo(VehiculoRequestDTO d){if(vehiculos.existsByPlaca(d.placa()))throw DomainException.conflict("La placa ya existe");Vehiculo v=new Vehiculo();mapper.vehiculo(v,d,c(d.clienteId()));vehiculos.saveAndFlush(v);log.info("Vehículo creado id={}",v.getId());return mapper.vehiculo(v);}
 @Transactional public void editarVehiculo(Long id,VehiculoRequestDTO d){Vehiculo v=v(id);if(vehiculos.existsByPlacaAndIdNot(d.placa(),id))throw DomainException.conflict("La placa ya existe");mapper.vehiculo(v,d,c(d.clienteId()));vehiculos.flush();log.info("Vehículo actualizado id={}",id);}
 @Transactional public void eliminarVehiculo(Long id){Vehiculo v=vehiculos.lockById(id).orElseThrow(()->DomainException.missing("Vehículo"));if(ordenes.existsByVehiculoId(id))throw DomainException.conflict("El vehículo tiene órdenes y no puede eliminarse");vehiculos.delete(v);vehiculos.flush();log.info("Vehículo eliminado id={}",id);}
}
